FILES = {'scripts/merge_claude_output.py': 'import pandas as pd\nimport re\nfrom pathlib import Path\n\nFINAL_REPORT = Path("reports/final_seo_report.csv")\nCLAUDE_FILE = Path("reports/claude_response.txt")\n\ndf = pd.read_csv(FINAL_REPORT)\ndf["URL"] = df["URL"].fillna("").astype(str).str.strip()\ndf["Issue"] = df["Issue"].fillna("").astype(str).str.strip()\n\nif "Risk Level" not in df.columns:\n    df["Risk Level"] = ""\n\ntext = CLAUDE_FILE.read_text(encoding="utf-8")\ntext = text.replace("\\\\n", "\\n")\n\n# Stop before Cross-Case Observations so it cannot leak into Case 10.\ntext = re.split(r"(?i)(?:---\\s*)?#{2,3}\\s*Cross-Case Observations", text)[0]\n\ncases = re.split(r"(?=##\\s*Case\\s+\\d+)", text)\nupdated = 0\n\nfor case in cases:\n    if not case.strip():\n        continue\n\n    url_match = re.search(\n        r"\\*\\*URL:\\*\\*\\s*(?:\\[[^\\]]+\\]\\()?([^\\s\\)]+)", case\n    )\n    issue_match = re.search(\n        r"\\*\\*SEO Issue:\\*\\*\\s*([^\\n]+)", case\n    )\n\n    if not url_match or not issue_match:\n        continue\n\n    url = url_match.group(1).strip().rstrip(")")\n    issue = issue_match.group(1).strip()\n\n    recommendation_match = re.search(\n        r"\\*\\*AI Recommendation:\\*\\*\\s*(.*?)(?=\\s*\\*\\*Human Review:\\*\\*)",\n        case, re.S\n    )\n    human_match = re.search(\n        r"\\*\\*Human Review:\\*\\*\\s*(.*?)(?=\\s*\\*\\*Risk Level:\\*\\*)",\n        case, re.S\n    )\n    risk_match = re.search(\n        r"\\*\\*Risk Level:\\*\\*\\s*(.*?)(?=\\s*(?:---|##\\s*Case|\\Z))",\n        case, re.S\n    )\n\n    recommendation = recommendation_match.group(1).strip() if recommendation_match else "Not provided"\n    human_review = human_match.group(1).strip() if human_match else "Required"\n    risk_level = risk_match.group(1).strip() if risk_match else "Not provided"\n\n    recommendation = re.sub(r"\\*\\*", "", recommendation)\n    human_review = re.sub(r"\\*\\*", "", human_review)\n    risk_level = re.sub(r"\\*\\*", "", risk_level)\n\n    recommendation = re.sub(r"\\s+", " ", recommendation).strip()\n    human_review = re.sub(r"\\s+", " ", human_review).strip()\n    risk_level = re.sub(r"\\s+", " ", risk_level).strip()\n\n    # Never allow a new section to remain inside Risk Level.\n    risk_level = re.split(\n        r"(?i)(?:---\\s*)?(?:#{2,3}\\s*)?(?:Cross-Case Observations|Case\\s+\\d+)",\n        risk_level\n    )[0].strip()\n\n    mask = (\n        (df["URL"] == url) &\n        (df["Issue"].str.lower() == issue.lower())\n    )\n\n    if mask.any():\n        df.loc[mask, "AI Recommendation"] = recommendation\n        df.loc[mask, "Human Review"] = human_review\n        df.loc[mask, "Risk Level"] = risk_level\n        df.loc[mask, "Status"] = "AI Reviewed"\n        updated += int(mask.sum())\n\ndf.to_csv(FINAL_REPORT, index=False, encoding="utf-8-sig")\n\nprint("\\n====================================")\nprint("CLAUDE OUTPUT MERGED SUCCESSFULLY")\nprint("====================================")\nprint("Rows updated:", updated)\nprint("Final report:", FINAL_REPORT)\nprint("\\nRisk Level Summary:")\nprint(df["Risk Level"].value_counts(dropna=False))\nprint("\\nAI Review Status:")\nprint(df["Status"].value_counts(dropna=False))\n', 'scripts/data_quality.py': 'import pandas as pd\nfrom pathlib import Path\n\nsrc = Path("data/gsc_data.csv")\nout = Path("reports/data_quality.csv")\n\ndf = pd.read_csv(src)\n\nfor col in ["Clicks", "Impressions", "CTR", "Position"]:\n    if col in df.columns:\n        df[col] = pd.to_numeric(df[col], errors="coerce")\n\nissues = []\n\nfor _, row in df.iterrows():\n    url = str(row.get("URL", "")).strip()\n    if not url or url.lower() == "nan":\n        continue\n\n    clicks = row.get("Clicks", 0)\n    impressions = row.get("Impressions", 0)\n    ctr = row.get("CTR", 0)\n\n    if pd.notna(clicks) and pd.notna(impressions) and impressions > 0:\n        derived_ctr = clicks / impressions * 100\n\n        if pd.notna(ctr) and ctr == 0 and clicks > 0:\n            issues.append({\n                "URL": url,\n                "Issue": "CTR Data Integrity Issue",\n                "Priority": "High",\n                "Current Value": f"CTR={ctr}%, Clicks={clicks}, Impressions={impressions}",\n                "Recommendation": f"Validate GSC export/tracking. Derived CTR is {derived_ctr:.2f}%."\n            })\n        elif pd.notna(ctr) and abs(float(ctr) - derived_ctr) > 0.5:\n            issues.append({\n                "URL": url,\n                "Issue": "CTR Data Mismatch",\n                "Priority": "Medium",\n                "Current Value": f"Reported CTR={ctr}%, Derived CTR={derived_ctr:.2f}%",\n                "Recommendation": "Validate the GSC export before using CTR for automated prioritisation."\n            })\n\npd.DataFrame(issues).to_csv(out, index=False, encoding="utf-8-sig")\nprint("Data quality report:", out)\nprint("Issues found:", len(issues))\n', 'scripts/dashboard_summary.py': 'import pandas as pd\nfrom pathlib import Path\n\nreport = Path("reports/final_seo_report.csv")\nout = Path("reports/dashboard_summary.csv")\n\ndf = pd.read_csv(report)\n\nsummary = [\n    ["Total report rows", len(df)],\n    ["AI Reviewed", int((df["Status"] == "AI Reviewed").sum())],\n    ["Pending", int((df["Status"] == "Pending").sum())],\n    ["High priority", int((df["Priority"].astype(str).str.upper() == "HIGH").sum())],\n    ["Medium priority", int((df["Priority"].astype(str).str.upper() == "MEDIUM").sum())],\n]\n\nif Path("reports/data_quality.csv").exists():\n    dq = pd.read_csv("reports/data_quality.csv")\n    summary.append(["Data quality issues", len(dq)])\n\npd.DataFrame(summary, columns=["Metric", "Value"]).to_csv(\n    out, index=False, encoding="utf-8-sig"\n)\n\nprint("Dashboard summary:", out)\n', 'scripts/run_all.py': 'import subprocess\nimport sys\nfrom pathlib import Path\n\nscripts = [\n    "scripts/gsc_analysis.py",\n    "scripts/technical_audit.py",\n    "scripts/ai_input_generator.py",\n    "scripts/create_claude_prompts.py",\n    "scripts/create_final_report.py",\n    "scripts/data_quality.py",\n]\n\nfor script in scripts:\n    print("\\n>>> Running", script)\n    result = subprocess.run([sys.executable, script])\n    if result.returncode != 0:\n        raise SystemExit(f"FAILED: {script}")\n\nclaude = Path("reports/claude_response.txt")\nif claude.exists() and claude.stat().st_size > 0:\n    print("\\n>>> Merging Claude output")\n    result = subprocess.run([sys.executable, "scripts/merge_claude_output.py"])\n    if result.returncode != 0:\n        raise SystemExit("FAILED: merge_claude_output.py")\nelse:\n    print("\\n>>> Claude response not found; skipping AI merge.")\n\nsubprocess.run([sys.executable, "scripts/dashboard_summary.py"])\n\nprint("\\n====================================")\nprint("SEO AUTOMATION PIPELINE COMPLETE")\nprint("====================================")\n', 'requirements.txt': 'pandas>=2.0,<4.0\npytest>=8.0,<9.0\n', 'tests/test_seo_rules.py': 'def test_ctr_derived_calculation():\n    clicks = 31500\n    impressions = 580000\n    ctr = clicks / impressions * 100\n    assert round(ctr, 2) == 5.43\n\ndef test_page_two_rule():\n    position = 14.2\n    impressions = 165000\n    assert 11 <= position <= 20 and impressions >= 500\n\ndef test_top_three_rule():\n    position = 2.8\n    impressions = 10000\n    assert 1 <= position <= 3 and impressions >= 1000\n', '.github/workflows/seo-audit.yml': 'name: Weekly SEO Audit\n\non:\n  workflow_dispatch:\n  schedule:\n    - cron: "0 6 * * 1"\n\njobs:\n  seo-audit:\n    runs-on: ubuntu-latest\n\n    steps:\n      - name: Checkout repository\n        uses: actions/checkout@v4\n\n      - name: Set up Python\n        uses: actions/setup-python@v5\n        with:\n          python-version: "3.12"\n\n      - name: Install dependencies\n        run: pip install -r requirements.txt\n\n      - name: Run SEO automation\n        run: python scripts/run_all.py\n\n      - name: Run tests\n        run: python -m pytest tests\n\n      - name: Upload reports\n        uses: actions/upload-artifact@v4\n        with:\n          name: seo-reports\n          path: reports/\n', 'README.md': '# Paytm SEO Automation — High-Scale Demonstration\n\n## Objective\n\nAutomate repetitive technical and on-page SEO analysis for a high-scale fintech website while keeping human approval for important production changes.\n\n> Paytm is used as a representative high-scale website. Where proprietary/internal data is unavailable, synthetic/sample data is used.\n\n## Architecture\n\nSEO Data (GSC / Crawl / Sitemap / PageSpeed / Logs)\n→ Python\n→ Rule Engine\n→ Issue Detection\n→ Claude AI Recommendations\n→ Human Review\n→ GitHub\n→ Implementation\n→ QA\n→ Monitoring\n\n## Automated tasks\n\n- GSC opportunity detection\n- Technical SEO issue detection\n- Priority classification\n- AI input generation\n- Claude prompt generation\n- Claude recommendation merge\n- CTR data-quality validation\n- Report generation\n- Dashboard summary\n- Scheduled GitHub Actions audit\n- Automated tests\n\n## Human approval required\n\nDo not automatically deploy:\n\n- canonical changes\n- redirects\n- noindex/robots changes\n- URL consolidation\n- major financial/YMYL content changes\n- production deployments\n\n## Claude\n\nThe demonstration can use Claude Free manually. Python prepares the SEO cases and Claude provides recommendations. Claude API integration is optional and can be added later when API credentials/billing are available.\n\n## Data-quality finding\n\nThe sample GSC data contains rows where CTR is 0 while clicks and impressions are non-zero.\n\nExample:\n\n31500 clicks / 580000 impressions × 100 = 5.43%\n\nThe pipeline flags this as a data-integrity issue instead of blindly trusting the source CTR.\n\n## Run\n\n```bash\npython scripts/run_all.py\n```\n\n## Tests\n\n```bash\npython -m pytest tests\n```\n\n## Main outputs\n\n- reports/gsc_opportunities.csv\n- reports/technical_seo_issues.csv\n- reports/ai_input.csv\n- reports/claude_prompts.txt\n- reports/final_seo_report.csv\n- reports/data_quality.csv\n- reports/dashboard_summary.csv\n\n## High-scale model\n\nFor 1,000,000 URLs, automation processes the full dataset, groups issues and prioritises high-impact cases. Humans review only the changes that require judgement.\n\n## Priority framework\n\n- P0 / Critical: mass indexation, robots, sitemap, canonical failures\n- P1 / High: broken links, duplicate titles, major crawl/internal-link problems\n- P2 / Medium: metadata/content opportunities\n- P3 / Low: minor optimisation\n\n## Production principle\n\nAI recommends and explains. Humans approve high-impact changes. GitHub provides version control, review and an audit trail.\n'}

